const COURSE_LESSON_HTML = {
  "kurssArticlesLesson": "\n  <h3>Articole</h3>\n\n  <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Articolul german nu coincide întotdeauna cu genul din limba română. De aceea, substantivele se învață cel mai bine împreună cu articolul.</div>\n  </div>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exemple de articole</h4>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Tisch — masă</div>\n      <div class=\"kurss-example\">die Tür — ușă</div>\n      <div class=\"kurss-example\">das Messer — cuțit</div>\n      <div class=\"kurss-example\">das Mädchen — fată</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♂</span>Adesea DER</h4>\n    <p class=\"artikuli-explain\">DER se folosește adesea pentru persoane de sex masculin, zile, luni, anotimpuri și unele cuvinte cu anumite terminații.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reguli</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-er → adesea DER, de exemplu: der Computer, der Lehrer <span class=\"artikuli-note\">dar nu întotdeauna</span></div>\n      <div class=\"kurss-example\">-ling → adesea DER, de exemplu: der Schmetterling</div>\n      <div class=\"kurss-example\">-ismus → adesea DER, de exemplu: der Tourismus, der Kapitalismus</div>\n      <div class=\"kurss-example\">persoane de sex masculin → der Mann, der Vater</div>\n      <div class=\"kurss-example\">profesii → der Lehrer, der Arzt</div>\n      <div class=\"kurss-example\">mărci de automobile → der BMW, der Mercedes</div>\n      <div class=\"kurss-example\">zile → der Montag, der Dienstag</div>\n      <div class=\"kurss-example\">luni → der August, der Dezember</div>\n      <div class=\"kurss-example\">anotimpuri → der Sommer, der Winter</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemple</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">der Mann — bărbat</div>\n      <div class=\"kurss-example\">der Vater — tată</div>\n      <div class=\"kurss-example\">der Montag — luni</div>\n      <div class=\"kurss-example\">der August — august</div>\n      <div class=\"kurss-example\">der Sommer — vară</div>\n      <div class=\"kurss-example\">der Lehrer — profesor</div>\n      <div class=\"kurss-example\">der Computer — calculator</div>\n      <div class=\"kurss-example\">der Schmetterling — fluture</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>♀</span>Adesea DIE</h4>\n    <p class=\"artikuli-explain\">DIE se folosește adesea pentru persoane de sex feminin, plural și cuvinte cu terminațiile -ung, -heit, -keit, -schaft, -ion, -tät, -ei.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reguli</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-ung → die Wohnung, die Rechnung</div>\n      <div class=\"kurss-example\">-heit → die Freiheit, die Gesundheit</div>\n      <div class=\"kurss-example\">-keit → die Möglichkeit</div>\n      <div class=\"kurss-example\">-schaft → die Mannschaft</div>\n      <div class=\"kurss-example\">-ion → die Nation</div>\n      <div class=\"kurss-example\">-tät → die Universität</div>\n      <div class=\"kurss-example\">-ei → die Polizei, die Bäckerei</div>\n      <div class=\"kurss-example\">persoane de sex feminin → die Frau, die Mutter</div>\n      <div class=\"kurss-example\">mărci de motociclete → die Harley-Davidson, die Yamaha</div>\n      <div class=\"kurss-example\">plural → die Autos, die Häuser</div>\n      <div class=\"kurss-example\">pluralul aproape întotdeauna → die Autos, die Häuser, die Kinder</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemple</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Frau — femeie</div>\n      <div class=\"kurss-example\">die Mutter — mamă</div>\n      <div class=\"kurss-example\">die Wohnung — apartament</div>\n      <div class=\"kurss-example\">die Rechnung — factură</div>\n      <div class=\"kurss-example\">die Freiheit — libertate</div>\n      <div class=\"kurss-example\">die Möglichkeit — posibilitate</div>\n      <div class=\"kurss-example\">die Mannschaft — echipă</div>\n      <div class=\"kurss-example\">die Nation — națiune</div>\n      <div class=\"kurss-example\">die Universität — universitate</div>\n      <div class=\"kurss-example\">die Polizei — poliție</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>◇</span>Adesea DAS</h4>\n    <p class=\"artikuli-explain\">DAS se folosește adesea pentru diminutivele cu -chen / -lein, multe cuvinte cu -ment / -um și verbele folosite ca substantive.</p>\n\n    <h5 class=\"artikuli-subtitle\">Reguli</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">-chen → das Mädchen, das Häuschen</div>\n      <div class=\"kurss-example\">-lein → das Fräulein</div>\n      <div class=\"kurss-example\">-ment → das Instrument</div>\n      <div class=\"kurss-example\">-um → das Zentrum, das Museum</div>\n      <div class=\"kurss-example\">metale → das Gold, das Silber, das Eisen</div>\n      <div class=\"kurss-example\">elemente chimice → das Eisen, das Kupfer</div>\n      <div class=\"kurss-example\">hoteluri → das Hotel</div>\n      <div class=\"kurss-example\">culori folosite ca substantive → das Rot, das Blau</div>\n      <div class=\"kurss-example\">verb folosit ca substantiv → das Essen, das Lernen</div>\n      <div class=\"kurss-example\">verbe folosite ca substantive → das Essen, das Lernen, das Lesen</div>\n    </div>\n\n    <h5 class=\"artikuli-subtitle\">Exemple</h5>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">das Kind — copil</div>\n      <div class=\"kurss-example\">das Mädchen — fată</div>\n      <div class=\"kurss-example\">das Häuschen — căsuță</div>\n      <div class=\"kurss-example\">das Instrument — instrument</div>\n      <div class=\"kurss-example\">das Zentrum — centru</div>\n      <div class=\"kurss-example\">das Museum — muzeu</div>\n      <div class=\"kurss-example\">das Essen — mâncat / mâncare</div>\n      <div class=\"kurss-example\">das Lernen — învățare</div>\n    </div>\n  </section>\n\n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>!</span>Excepții importante / de învățat cu articolul</h4>\n    <p class=\"artikuli-explain\">La unele cuvinte, articolul nu poate fi stabilit cu siguranță după terminație sau după genul din limba română. Acestea se învață cel mai bine împreună cu articolul.</p>\n    <div class=\"artikuli-grid\">\n      <div class=\"kurss-example\">die Tür — ușă</div>\n      <div class=\"kurss-example\">das Messer — cuțit</div>\n      <div class=\"kurss-example\">die Sonne — soare</div>\n      <div class=\"kurss-example\">der Mond — lună</div>\n      <div class=\"kurss-example\">das Mädchen — fată</div>\n      <div class=\"kurss-example\">das Auto — automobil</div>\n      <div class=\"kurss-example\">der Käse — brânză</div>\n      <div class=\"kurss-example\">die Gabel — furculiță</div>\n    </div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Terminațiile și grupurile de cuvinte te ajută să ghicești articolul, dar nu sunt o regulă sigură 100%. Dacă nu ești sigur, învață cuvântul împreună cu articolul.</div>\n  </div>\n",
  "kurssPronounsLesson": "\n  <h3>Pronume</h3>\n            <div class=\"artikuli-info artikuli-intro-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ, Akkusativ și Dativ — formele pronumelor.</div>\n  </div>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>N</span>Nominativ — cine?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">ich — eu</div><div class=\"kurss-example\">du — tu</div><div class=\"kurss-example\">er — el</div><div class=\"kurss-example\">sie — ea</div><div class=\"kurss-example\">es — el / ea</div><div class=\"kurss-example\">wir — noi</div><div class=\"kurss-example\">ihr — voi</div><div class=\"kurss-example\">sie — ei / ele</div><div class=\"kurss-example\">Sie — dumneavoastră (de politețe)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>A</span>Akkusativ — pe cine?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mich — pe mine</div><div class=\"kurss-example\">dich — pe tine</div><div class=\"kurss-example\">ihn — pe el (m.)</div><div class=\"kurss-example\">sie — pe ea (f.)</div><div class=\"kurss-example\">es — pe el / pe ea</div><div class=\"kurss-example\">uns — pe noi</div><div class=\"kurss-example\">euch — pe voi</div><div class=\"kurss-example\">sie — pe ei / pe ele</div><div class=\"kurss-example\">Sie — pe dumneavoastră (de politețe)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>D</span>Dativ — cui?</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">mir — mie</div><div class=\"kurss-example\">dir — ție</div><div class=\"kurss-example\">ihm — lui</div><div class=\"kurss-example\">ihr — ei</div><div class=\"kurss-example\">uns — nouă</div><div class=\"kurss-example\">euch — vouă</div><div class=\"kurss-example\">ihnen — lor</div><div class=\"kurss-example\">Ihnen — dumneavoastră (de politețe)</div></div>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>?</span>Cum alegi forma?</h4>\n    <ul class=\"kurss-summary-list\"><li><span class=\"case-blue\">Nominativ</span> — subiectul propoziției (cine face acțiunea?)</li><li><span class=\"case-red\">Akkusativ</span> — complementul direct (pe cine?)</li><li><span class=\"case-green\">Dativ</span> — complementul indirect (cui?)</li></ul>\n  </section>\n\n            \n  <section class=\"artikuli-block\">\n    <h4 class=\"artikuli-header\"><span>•</span>Exemple</h4>\n    <div class=\"artikuli-grid\"><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">dich</span>. — Te văd.</div><div class=\"kurss-example\">Ich sehe <span class=\"case-red\">ihn</span>. — Îl văd.</div><div class=\"kurss-example\">Wir mögen <span class=\"case-red\">euch</span>. — Ne placeți.</div><div class=\"kurss-example\">Ich helfe <span class=\"case-green\">dir</span>. — Te ajut.</div><div class=\"kurss-example\">Ich gebe <span class=\"case-green\">ihm</span> ein Buch. — Îi dau o carte.</div><div class=\"kurss-example\">Wir danken <span class=\"case-green\">euch</span>. — Vă mulțumim.</div></div>\n  </section>\n\n  <div class=\"artikuli-info artikuli-bottom-info\">\n    <span class=\"artikuli-info-icon\">i</span>\n    <div>Nominativ este întotdeauna subiectul propoziției, iar Akkusativ și Dativ sunt complemente. Uită-te la verb și întreabă: <span class=\"case-red\">pe cine?</span> sau <span class=\"case-green\">cui?</span></div>\n  </div>\n",
  "kurssPronunciationLesson": "\n            <h3>Vocale — lungi și scurte</h3>\n            <p class=\"kurss-lesson-intro\">În limba germană, vocalele pot fi lungi sau scurte. Acest lucru influențează pronunția cuvântului.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocală lungă</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">warm (varm) — cald</div><div class=\"kurss-example\">gut (gūt) — bun</div><div class=\"kurss-example\">Tat (tāt) — faptă / acțiune</div><div class=\"kurss-example\">Flur (flūr) — hol / coridor</div><div class=\"kurss-example\">Weg (vēc) — drum / cale</div><div class=\"kurss-example\">Hut (hūt) — pălărie</div><div class=\"kurss-example\">Hof (hōf) — curte</div><div class=\"kurss-example\">Schlaf (șlāf) — somn</div></div>\n              <p>Dacă după vocală urmează o singură consoană, vocala se pronunță adesea lung.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocală scurtă</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Pilz (pilț) — ciupercă</div><div class=\"kurss-example\">Wort (vort) — cuvânt</div><div class=\"kurss-example\">Mund (munt) — gură</div><div class=\"kurss-example\">bald (balt) — curând</div><div class=\"kurss-example\">scharf (șarf) — ascuțit / picant</div><div class=\"kurss-example\">Feld (felt) — câmp</div><div class=\"kurss-example\">voll (fol) — plin</div></div>\n              <p>Dacă după vocală urmează două sau mai multe consoane, vocala se pronunță adesea scurt.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminațiile en / el / er</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">singen (zinghen) — a cânta</div><div class=\"kurss-example\">tragen (trāghen) — a purta / a duce</div><div class=\"kurss-example\">Garten (garten) — grădină</div><div class=\"kurss-example\">Vogel (fōghel) — pasăre</div><div class=\"kurss-example\">Segel (zēghel) — velă / pânză</div><div class=\"kurss-example\">Braten (brāten) — friptură</div><div class=\"kurss-example\">Bogen (bōghen) — arc</div><div class=\"kurss-example\">Spiegel (șpīghel) — oglindă</div><div class=\"kurss-example\">Finger (fingher) — deget</div><div class=\"kurss-example\">Halter (halter) — suport</div><div class=\"kurss-example\">Arbeiter (arbaiter) — muncitor</div><div class=\"kurss-example\">Häuser (hoizer) — case</div><div class=\"kurss-example\">wieder (vīder) — din nou</div><div class=\"kurss-example\">breiter (braiter) — mai lat</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Litera h ca semn de lungire</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rahmen (rāmen) — ramă / cadru</div><div class=\"kurss-example\">Ohr (ōr) — ureche</div><div class=\"kurss-example\">Kohle (cōle) — cărbune</div><div class=\"kurss-example\">Zahl (țāl) — număr</div><div class=\"kurss-example\">ihn (īn) — pe el</div><div class=\"kurss-example\">ihm (īm) — lui (dativ)</div><div class=\"kurss-example\">Huhn (hūn) — găină</div><div class=\"kurss-example\">nahm (nām) — a luat / luă</div><div class=\"kurss-example\">nehmen (nēmen) — a lua</div><div class=\"kurss-example\">Schuh (șū) — pantof</div></div>\n              <p>În unele cuvinte, h lungește vocala dinaintea sa. În aceste cazuri, h de obicei nu se pronunță.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Terminații în e</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Lampe (lampe) — lampă</div><div class=\"kurss-example\">Hase (hāze) — iepure</div><div class=\"kurss-example\">Knabe (cnābe) — băiat</div><div class=\"kurss-example\">Rabe (rābe) — corb</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>I lung = ie</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">die (dī) — articolul „die”</div><div class=\"kurss-example\">diese (dīze) — aceasta / aceștia</div><div class=\"kurss-example\">wieder (vīder) — din nou</div><div class=\"kurss-example\">Fliege (flīghe) — muscă</div><div class=\"kurss-example\">Ziege (țīghe) — capră</div><div class=\"kurss-example\">Stiel (ștīl) — coadă (mâner) / tulpină</div><div class=\"kurss-example\">Dieb (dīp) — hoț</div><div class=\"kurss-example\">hier (hīr) — aici</div></div>\n              <p>În germană, i lung se scrie adesea ie.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Vocale duble</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Saal (zāl) — sală</div><div class=\"kurss-example\">Saat (zāt) — semănat / sămânță</div><div class=\"kurss-example\">Staat (ștāt) — stat</div><div class=\"kurss-example\">Beere (bēre) — boabă / fruct de pădure</div><div class=\"kurss-example\">See (zē) — lac / mare</div><div class=\"kurss-example\">Beet (bēt) — strat (de flori sau legume)</div><div class=\"kurss-example\">Boot (bōt) — barcă</div><div class=\"kurss-example\">Moor (mōr) — mlaștină / turbărie</div><div class=\"kurss-example\">Moos (mōs) — mușchi (plantă)</div></div>\n              <p>Vocalele duble se pronunță de obicei lung.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ä</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Wand (vant) — perete</div><div class=\"kurss-example\">Wände (vende) — pereți</div><div class=\"kurss-example\">Vater (fāter) — tată</div><div class=\"kurss-example\">Väter (fēter) — tați</div><div class=\"kurss-example\">Schrank (șranc) — dulap</div><div class=\"kurss-example\">Schränke (șrenche) — dulapuri</div><div class=\"kurss-example\">Bank (banc) — bancă (de șezut) / bancă</div><div class=\"kurss-example\">Bänke (benche) — bănci (de șezut)</div><div class=\"kurss-example\">Tal (tāl) — vale</div><div class=\"kurss-example\">Täler (tēler) — văi</div></div>\n              <p>ä este umlautul (metafonia) lui a.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ö</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Rose (rōze) — trandafir</div><div class=\"kurss-example\">Röschen (rȫs-hen) — trandafiraș</div><div class=\"kurss-example\">Ofen (ōfen) — cuptor / sobă</div><div class=\"kurss-example\">Öfen (ȫfen) — cuptoare / sobe</div><div class=\"kurss-example\">Rock (roc) — fustă</div><div class=\"kurss-example\">Röcke (röche) — fuste</div></div>\n              <p>ö este umlautul (metafonia) lui o.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ü</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kurz (curț) — scurt</div><div class=\"kurss-example\">kürzer (cürțer) — mai scurt</div><div class=\"kurss-example\">Kunst (cunst) — artă</div><div class=\"kurss-example\">Künste (cünste) — arte</div><div class=\"kurss-example\">Mutter (muter) — mamă</div><div class=\"kurss-example\">Mütter (müter) — mame</div></div>\n              <p>ü este umlautul (metafonia) lui u.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftongi: äu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Baum (baum) — copac</div><div class=\"kurss-example\">Bäume (boime) — copaci</div><div class=\"kurss-example\">Haus (haus) — casă</div><div class=\"kurss-example\">Häuser (hoizer) — case</div><div class=\"kurss-example\">Strauch (ștrauh) — tufiș / arbust</div><div class=\"kurss-example\">Sträucher (ștroiher) — tufișuri / arbuști</div><div class=\"kurss-example\">Maus (maus) — șoarece</div><div class=\"kurss-example\">Mäuse (moize) — șoareci</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftongi: eu</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">heute (hoite) — azi</div><div class=\"kurss-example\">Leute (loite) — oameni</div><div class=\"kurss-example\">neu (noi) — nou</div><div class=\"kurss-example\">neun (noin) — nouă</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Diftongi: ei</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">mein (main) — meu</div><div class=\"kurss-example\">dein (dain) — tău</div><div class=\"kurss-example\">sein (zain) — său / sa / a fi</div><div class=\"kurss-example\">frei (frai) — liber</div><div class=\"kurss-example\">arbeiten (arbaiten) — a lucra / a munci</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Note de pronunție pentru lecția 2</h4>\n              <ul class=\"kurss-summary-list\"><li>în cuvintele ich, nicht, rechnen, zeichnen, „ch” se pronunță moale (ca „h” din „hienă”)</li><li>în cuvintele arbeiten și zeichnen, „ei” se pronunță ca „ai”</li><li>„sp” la începutul cuvântului se pronunță ca „șp”</li><li>în verbul tun, litera „u” se pronunță lung</li></ul>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Rezumat</h4>\n              <ul class=\"kurss-summary-list\"><li>o singură consoană după vocală → adesea vocală lungă</li><li>două sau mai multe consoane → adesea vocală scurtă</li><li>h poate lungi vocala</li><li>ie înseamnă adesea i lung</li><li>vocalele duble sunt de obicei lungi</li></ul>\n            </section>",
  "kurssConsonantsLesson": "\n            <h3>Consoane și combinații de litere</h3>\n            <p class=\"kurss-lesson-intro\">În germană, unele consoane și combinații de litere se pronunță altfel decât se scriu. În această lecție găsiți cele mai importante exemple pentru începători.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Consoane</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">das Rad (rāt) — roată</div><div class=\"kurss-example\">die Räder (rēder) — roți</div><div class=\"kurss-example\">Bad (bāt) — baie</div><div class=\"kurss-example\">Bäder (bēder) — băi</div></div>\n              <p>La sfârșitul cuvântului, consoanele adesea nu se pronunță la fel cum se scriu.</p>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ch</h4>\n              <p>„ch” se poate pronunța moale sau aspru. În unele cuvinte sună ca un „h” moale (ca în „hienă”), în altele ca un „h” aspru (ca în „duh”).</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">rechnen (rehnen) — a calcula / a socoti</div><div class=\"kurss-example\">zeichnen (țaihnen) — a desena</div><div class=\"kurss-example\">nicht (niht) — nu</div><div class=\"kurss-example\">schlecht (șleht) — rău / prost</div><div class=\"kurss-example\">mich (mih) — pe mine</div><div class=\"kurss-example\">dich (dih) — pe tine</div><div class=\"kurss-example\">Strauch (ștrauh) — tufiș / arbust</div><div class=\"kurss-example\">noch (noh) — încă</div><div class=\"kurss-example\">Nacht (naht) — noapte</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sch</h4>\n              <p>„sch” se pronunță în germană ca „ș” din română.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Schule (șūle) — școală</div><div class=\"kurss-example\">Schüler (șǖler) — elev</div><div class=\"kurss-example\">Schiff (șif) — navă / vapor</div><div class=\"kurss-example\">Schraube (șraube) — șurub</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>sp și st la începutul cuvântului</h4>\n              <p>La începutul cuvântului sau al silabei, „sp” se pronunță adesea ca „șp”, iar „st” ca „șt”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen (șpīlen) — a (se) juca</div><div class=\"kurss-example\">Sprung (șprung) — săritură</div><div class=\"kurss-example\">stehen (ștēen) — a sta (în picioare)</div><div class=\"kurss-example\">Stall (ștal) — grajd</div><div class=\"kurss-example\">Stand (ștant) — poziție / stand</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>qu</h4>\n              <p>„qu” se pronunță în germană de obicei ca „cv”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Qual (cvāl) — chin</div><div class=\"kurss-example\">Quartier (cvartīr) — cartier / cazare</div><div class=\"kurss-example\">quer (cvēr) — transversal / de-a curmezișul</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>s și z</h4>\n              <p>La începutul cuvântului, „s” sună adesea ca „z”. Litera „z” sună în germană ca „ț” din română.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">sagen (zāghen) — a spune</div><div class=\"kurss-example\">singen (zinghen) — a cânta</div><div class=\"kurss-example\">Rose (rōze) — trandafir</div><div class=\"kurss-example\">Zahl (țāl) — număr</div><div class=\"kurss-example\">Zeit (țait) — timp</div><div class=\"kurss-example\">Zink (țink) — zinc</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>v</h4>\n              <p>În germană, „v” se pronunță adesea ca „f”. În cuvintele de origine străină sună adesea ca „v” din română.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Vater (fāter) — tată</div><div class=\"kurss-example\">von (fon) — de la / din</div><div class=\"kurss-example\">viel (fīl) — mult</div><div class=\"kurss-example\">vier (fīr) — patru</div><div class=\"kurss-example\">Villa (vila) — vilă</div><div class=\"kurss-example\">Klavier (clavīr) — pian</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>x și y</h4>\n              <p>„x” se pronunță ca „cs”. „y” se pronunță în unele cuvinte ca „ü”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Felix (fēlics) — Felix</div><div class=\"kurss-example\">Axt (acst) — topor</div><div class=\"kurss-example\">Mystik (müstic) — mistică</div><div class=\"kurss-example\">Mythe (mǖte) — mit</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>ß</h4>\n              <p>„ß” se pronunță în germană ca „s”.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Fuß (fūs) — picior / laba piciorului</div><div class=\"kurss-example\">Füße (fǖse) — picioare</div><div class=\"kurss-example\">Grüße (grǖse) — salutări</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Rezumat</h4>\n              <ul class=\"kurss-summary-list\"><li>sch → ș</li><li>sp / st la început → șp / șt</li><li>qu → cv</li><li>z → ț</li><li>v adesea → f</li><li>x → cs</li><li>ß → s</li></ul>\n            </section>",
  "kurssVerbBasicsLesson": "\n            <h3>Bazele verbelor</h3>\n            <p class=\"kurss-lesson-intro\">Verbele din lecția 1 și formele lor (conjugarea)</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbe</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">kommen — a veni</div><div class=\"kurss-example\">gehen — a merge</div><div class=\"kurss-example\">stehen — a sta (în picioare)</div><div class=\"kurss-example\">singen — a cânta</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>kommen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich komme — eu vin</div><div class=\"kurss-example\">du kommst — tu vii</div><div class=\"kurss-example\">er kommt — el vine</div><div class=\"kurss-example\">sie kommt — ea vine</div><div class=\"kurss-example\">wir kommen — noi venim</div><div class=\"kurss-example\">ihr kommt — voi veniți</div><div class=\"kurss-example\">sie kommen — ei / ele vin</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>gehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich gehe — eu merg</div><div class=\"kurss-example\">du gehst — tu mergi</div><div class=\"kurss-example\">er geht — el merge</div><div class=\"kurss-example\">sie geht — ea merge</div><div class=\"kurss-example\">wir gehen — noi mergem</div><div class=\"kurss-example\">ihr geht — voi mergeți</div><div class=\"kurss-example\">sie gehen — ei / ele merg</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>stehen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich stehe — eu stau</div><div class=\"kurss-example\">du stehst — tu stai</div><div class=\"kurss-example\">er steht — el stă</div><div class=\"kurss-example\">sie steht — ea stă</div><div class=\"kurss-example\">wir stehen — noi stăm</div><div class=\"kurss-example\">ihr steht — voi stați</div><div class=\"kurss-example\">sie stehen — ei / ele stau</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>singen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich singe — eu cânt</div><div class=\"kurss-example\">du singst — tu cânți</div><div class=\"kurss-example\">er singt — el cântă</div><div class=\"kurss-example\">sie singt — ea cântă</div><div class=\"kurss-example\">wir singen — noi cântăm</div><div class=\"kurss-example\">ihr singt — voi cântați</div><div class=\"kurss-example\">sie singen — ei / ele cântă</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Verbele din lecția 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">spielen — a juca</div><div class=\"kurss-example\">arbeiten — a lucra</div><div class=\"kurss-example\">fragen — a întreba</div><div class=\"kurss-example\">antworten — a răspunde</div><div class=\"kurss-example\">rechnen — a calcula</div><div class=\"kurss-example\">zeichnen — a desena</div><div class=\"kurss-example\">tun — a face</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>spielen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich spiele — eu joc</div><div class=\"kurss-example\">du spielst — tu joci</div><div class=\"kurss-example\">er spielt — el joacă</div><div class=\"kurss-example\">sie spielt — ea joacă</div><div class=\"kurss-example\">wir spielen — noi jucăm</div><div class=\"kurss-example\">ihr spielt — voi jucați</div><div class=\"kurss-example\">sie spielen — ei / ele joacă</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>arbeiten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich arbeite — eu lucrez</div><div class=\"kurss-example\">du arbeitest — tu lucrezi</div><div class=\"kurss-example\">er arbeitet — el lucrează</div><div class=\"kurss-example\">sie arbeitet — ea lucrează</div><div class=\"kurss-example\">wir arbeiten — noi lucrăm</div><div class=\"kurss-example\">ihr arbeitet — voi lucrați</div><div class=\"kurss-example\">sie arbeiten — ei / ele lucrează</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>fragen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich frage — eu întreb</div><div class=\"kurss-example\">du fragst — tu întrebi</div><div class=\"kurss-example\">er fragt — el întreabă</div><div class=\"kurss-example\">sie fragt — ea întreabă</div><div class=\"kurss-example\">wir fragen — noi întrebăm</div><div class=\"kurss-example\">ihr fragt — voi întrebați</div><div class=\"kurss-example\">sie fragen — ei / ele întreabă</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>antworten</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich antworte — eu răspund</div><div class=\"kurss-example\">du antwortest — tu răspunzi</div><div class=\"kurss-example\">er antwortet — el răspunde</div><div class=\"kurss-example\">sie antwortet — ea răspunde</div><div class=\"kurss-example\">wir antworten — noi răspundem</div><div class=\"kurss-example\">ihr antwortet — voi răspundeți</div><div class=\"kurss-example\">sie antworten — ei / ele răspund</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>rechnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich rechne — eu calculez</div><div class=\"kurss-example\">du rechnest — tu calculezi</div><div class=\"kurss-example\">er rechnet — el calculează</div><div class=\"kurss-example\">sie rechnet — ea calculează</div><div class=\"kurss-example\">wir rechnen — noi calculăm</div><div class=\"kurss-example\">ihr rechnet — voi calculați</div><div class=\"kurss-example\">sie rechnen — ei / ele calculează</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>zeichnen</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich zeichne — eu desenez</div><div class=\"kurss-example\">du zeichnest — tu desenezi</div><div class=\"kurss-example\">er zeichnet — el desenează</div><div class=\"kurss-example\">sie zeichnet — ea desenează</div><div class=\"kurss-example\">wir zeichnen — noi desenăm</div><div class=\"kurss-example\">ihr zeichnet — voi desenați</div><div class=\"kurss-example\">sie zeichnen — ei / ele desenează</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>tun</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">ich tue — eu fac</div><div class=\"kurss-example\">du tust — tu faci</div><div class=\"kurss-example\">er tut — el face</div><div class=\"kurss-example\">sie tut — ea face</div><div class=\"kurss-example\">wir tun — noi facem</div><div class=\"kurss-example\">ihr tut — voi faceți</div><div class=\"kurss-example\">sie tun — ei / ele fac</div></div>\n            </section>",
  "kurssSentenceStructureLesson": "\n            <h3>Structura propoziției</h3>\n            <p class=\"kurss-lesson-intro\">În propoziția interogativă, verbul în limba germană stă de obicei pe primul loc.</p>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Exemple</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Du kommst. — Tu vii.</div><div class=\"kurss-example\">Kommst du? — Vii?</div><div class=\"kurss-example\">Er singt. — El cântă.</div><div class=\"kurss-example\">Singt er? — Cântă el?</div><div class=\"kurss-example\">Stehst du? — Stai în picioare?</div><div class=\"kurss-example\">Ja, ich stehe. — Da, stau în picioare.</div><div class=\"kurss-example\">Geht ihr? — Mergeți?</div><div class=\"kurss-example\">Ja, wir gehen. — Da, mergem.</div></div>\n            </section>\n            <section class=\"kurss-lesson-section\">\n              <h4>Întrebări cu „was”</h4>\n              <p>Dacă întrebarea începe cu un cuvânt interogativ, verbul în limba germană stă de obicei imediat după cuvântul interogativ.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Was tust du? — Ce faci?</div><div class=\"kurss-example\">Was tut er? — Ce face el?</div><div class=\"kurss-example\">Was tut sie? — Ce face ea?</div><div class=\"kurss-example\">Was tun sie? — Ce fac ei / ele?</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Negația cu „nicht”</h4>\n              <p>Dacă negația „nicht” se referă la verb, în limba germană ea stă de obicei după verb.</p>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Ich spiele nicht. — Nu mă joc.</div><div class=\"kurss-example\">Paul fragt nicht. — Paul nu întreabă.</div><div class=\"kurss-example\">Er kommt nicht. — El nu vine.</div><div class=\"kurss-example\">Sie singen nicht. — Ei / ele nu cântă.</div></div>\n            </section>\n\n            <section class=\"kurss-lesson-section\">\n              <h4>Propoziții din lecția 2</h4>\n              <div class=\"kurss-examples\"><div class=\"kurss-example\">Spielst du? — Te joci?</div><div class=\"kurss-example\">Nein, ich spiele nicht, ich arbeite. — Nu, nu mă joc, lucrez.</div><div class=\"kurss-example\">Paul fragt nicht, er arbeitet. — Paul nu întreabă, el lucrează.</div><div class=\"kurss-example\">Arbeitest du? — Lucrezi?</div><div class=\"kurss-example\">Nein, ich arbeite nicht, ich singe. — Nu, nu lucrez, cânt.</div><div class=\"kurss-example\">Was tut Paul? — Ce face Paul?</div><div class=\"kurss-example\">Er spielt. — El se joacă.</div><div class=\"kurss-example\">Was tut Marie? — Ce face Maria?</div><div class=\"kurss-example\">Sie singt. — Ea cântă.</div><div class=\"kurss-example\">Paul spielt, aber Marie singt. — Paul se joacă, dar Maria cântă.</div><div class=\"kurss-example\">Singt ihr? — Cântați?</div><div class=\"kurss-example\">Nein, wir singen nicht, wir arbeiten. — Nu, nu cântăm, lucrăm.</div><div class=\"kurss-example\">Was tun Paul und Marie? — Ce fac Paul și Maria?</div><div class=\"kurss-example\">Sie fragen. — Ei întreabă.</div><div class=\"kurss-example\">Sie antworten nicht. — Ei nu răspund.</div><div class=\"kurss-example\">Wer arbeitet? — Cine lucrează?</div><div class=\"kurss-example\">Wir arbeiten. — Noi lucrăm.</div><div class=\"kurss-example\">Wir rechnen und zeichnen. — Noi socotim și desenăm.</div><div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen. — Ei / ele vin, întreabă, răspund, lucrează, se joacă, cântă și pleacă.</div></div>\n            </section>",
  "kurssLesson2": "            <h3>Lecția 2</h3>\n            <p class=\"kurss-lesson-intro\">A doua lecție: dialoguri, cuvinte, pronunție, gramatică și traducere.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">Spielst du?<br>Nein, ich spiele nicht, ich arbeite.</div>\n                  <div class=\"kurss-example\">Paul fragt nicht, er arbeitet.</div>\n                  <div class=\"kurss-example\">Arbeitest du?<br>Nein, ich arbeite nicht, ich singe.</div>\n                  <div class=\"kurss-example\">Was tut Paul?<br>Er spielt.</div>\n                  <div class=\"kurss-example\">Was tut Marie?<br>Sie singt.</div>\n                  <div class=\"kurss-example\">Paul spielt, aber Marie singt.</div>\n                  <div class=\"kurss-example\">Singt ihr?<br>Nein, wir singen nicht, wir arbeiten.</div>\n                  <div class=\"kurss-example\">Was tun Paul und Marie?<br>Sie fragen.<br>Sie antworten nicht.</div>\n                  <div class=\"kurss-example\">Wer arbeitet?<br>Wir arbeiten.<br>Wir rechnen und zeichnen.</div>\n                  <div class=\"kurss-example\">Sie kommen, sie fragen, sie antworten, sie arbeiten, sie spielen, sie singen, sie gehen.</div>\n                </div>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\">\n                  <div class=\"kurss-example\">spielen — a se juca; a juca</div>\n                  <div class=\"kurss-example\">nein — nu</div>\n                  <div class=\"kurss-example\">nicht — nu</div>\n                  <div class=\"kurss-example\">arbeiten — a lucra</div>\n                  <div class=\"kurss-example\">fragen — a întreba</div>\n                  <div class=\"kurss-example\">was tut er? — ce face el?</div>\n                  <div class=\"kurss-example\">was tun sie? — ce fac ei / ele?</div>\n                  <div class=\"kurss-example\">aber — dar</div>\n                  <div class=\"kurss-example\">antworten — a răspunde</div>\n                  <div class=\"kurss-example\">rechnen — a socoti, a calcula</div>\n                  <div class=\"kurss-example\">zeichnen — a desena</div>\n                  <div class=\"kurss-example\">Marie — Maria</div>\n                </div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În cuvintele ich, nicht, rechnen, zeichnen, sunetul ch se pronunță moale, aproximativ ca h din cuvintele românești: hienă, hibrid.</div><div class=\"kurss-example\">În cuvintele arbeiten, zeichnen, diftongul ei se pronunță aproximativ ca un a deschis urmat de i, adică aproape ca ai.</div><div class=\"kurss-example\">Grupul de consoane sp se pronunță ca șp: spielen (șpilen).</div><div class=\"kurss-example\">În verbul tun, u se pronunță lung la toate persoanele.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>1</span>Terminații cu e</h4>\n                  <div class=\"lesson1-grammar-note\">Dacă tema verbului se termină în t, d, chn, atunci la conjugare înaintea terminațiilor -st și -t apare un e.</div>\n                  <h5 class=\"lesson2-subtitle\">arbeiten</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich arbeite</div><div class=\"kurss-example\">du arbeitest</div><div class=\"kurss-example\">er arbeitet</div><div class=\"kurss-example\">sie arbeitet</div><div class=\"kurss-example\">wir arbeiten</div><div class=\"kurss-example\">ihr arbeitet</div><div class=\"kurss-example\">sie arbeiten</div></div>\n                  <h5 class=\"lesson2-subtitle\">rechnen</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich rechne</div><div class=\"kurss-example\">du rechnest</div><div class=\"kurss-example\">er rechnet</div><div class=\"kurss-example\">sie rechnet</div><div class=\"kurss-example\">wir rechnen</div><div class=\"kurss-example\">ihr rechnet</div><div class=\"kurss-example\">sie rechnen</div></div>\n                  <h5 class=\"lesson2-subtitle\">tun</h5>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich tue</div><div class=\"kurss-example\">du tust</div><div class=\"kurss-example\">er tut</div><div class=\"kurss-example\">sie tut</div><div class=\"kurss-example\">wir tun</div><div class=\"kurss-example\">ihr tut</div><div class=\"kurss-example\">sie tun</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>2</span>Cuvântul interogativ</h4>\n                  <div class=\"lesson1-grammar-note\">În propozițiile interogative care încep cu un cuvânt interogativ, de exemplu: ce? cine? care? de ce? pentru ce? etc., verbul stă imediat după cuvântul interogativ.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Was tust du? — Ce faci?</div><div class=\"kurss-example\">Was tut er? — Ce face el?</div><div class=\"kurss-example\">Was tut sie? — Ce face ea?</div><div class=\"kurss-example\">Was tun sie? — Ce fac ei / ele?</div></div>\n                </section>\n                <section class=\"lesson1-block\">\n                  <h4 class=\"lesson1-grammar-header\"><span>3</span>Negația cu nicht</h4>\n                  <div class=\"lesson1-grammar-note\">Dacă negația nicht se referă la verb, ea stă după verb.</div>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Er kommt nicht. — El nu vine.</div><div class=\"kurss-example\">Sie singen nicht. — Ei nu cântă.</div></div>\n                </section>\n              </div>\n            </details>\n                                    <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson2-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 2: cartonaș de traducere\">\n                    <span class=\"lesson1-training-progress\">Lecția 2 · Tradu: 1 / 15</span>\n                    <span class=\"lesson1-training-text\">Cine întreabă?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p>\n                </div>\n              </div>\n            </details>",
  "kurssLesson6": "\n    <h3>Lecția 6</h3>\n    <p class=\"kurss-lesson-intro\">Numeralele, pluralul, umlauturile și formele de plural ale substantivelor.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier liegt ein Bleistift.</div><div class=\"kurss-example\">Dort liegen einige Messer.</div><div class=\"kurss-example\">Edgar nimmt ein Messer, zwei Messer, drei Messer.</div><div class=\"kurss-example\">Er legt die Messer wieder hin.</div><div class=\"kurss-example\">Alle Messer sind scharf.</div><div class=\"kurss-example\">Dann nimmt er wieder ein Messer.</div><div class=\"kurss-example\">Er macht das Messer auf.</div><div class=\"kurss-example\">Er nimmt den Bleistift.</div><div class=\"kurss-example\">Er spitzt den Bleistift an.</div><div class=\"kurss-example\">Er legt das Messer hin.</div><div class=\"kurss-example\">Er setzt sich und zeichnet.</div><div class=\"kurss-example\">Was zeichnet er? Er zeichnet einen Schlüssel.</div><div class=\"kurss-example\">Gertrud zeichnet ein Fenster und eine Tafel.</div><div class=\"kurss-example\">Anna zeichnet einen Garten.</div><div class=\"kurss-example\">Hier liegen vier Löffel.</div><div class=\"kurss-example\">Dort liegen fünf Nadeln.</div><div class=\"kurss-example\">Gertrud kommt und zählt die Löffel: das ist ein Löffel; das sind zwei, drei, vier Löffel.</div><div class=\"kurss-example\">Anna zählt die Nadeln: das ist eine Nadel; das sind zwei, drei, vier, fünf Nadeln.</div><div class=\"kurss-example\">Wieviel Nadeln sind hier?</div><div class=\"kurss-example\">Hier ist eine Nadel.</div><div class=\"kurss-example\">Dort sind zwei, drei, vier Nadeln.</div><div class=\"kurss-example\">Fünf Schlüssel sind hier.</div><div class=\"kurss-example\">Sechs Löffel sind dort.</div><div class=\"kurss-example\">Was ist das?</div><div class=\"kurss-example\">Das ist ein Hammer. Das sind fünf Hämmer.</div><div class=\"kurss-example\">Das ist ein Deckel. Das sind sechs Deckel.</div><div class=\"kurss-example\">Das ist ein Eimer. Das sind sieben Eimer.</div><div class=\"kurss-example\">Das ist ein Teller. Das sind acht Teller.</div><div class=\"kurss-example\">Das ist ein Wagen. Das sind neun Wagen.</div><div class=\"kurss-example\">Das ist ein Schlitten. Das sind zehn Schlitten.</div><div class=\"kurss-example\">Wie sind die Dinge?</div><div class=\"kurss-example\">Der Hammer ist klein. Die Hämmer sind klein.</div><div class=\"kurss-example\">Der Deckel ist groß. Die Deckel sind groß.</div><div class=\"kurss-example\">Der Eimer ist voll. Die Eimer sind voll.</div><div class=\"kurss-example\">Der Teller ist leer. Die Teller sind leer.</div><div class=\"kurss-example\">Der Wagen ist schwer. Die Wagen sind schwer.</div><div class=\"kurss-example\">Der Schlitten ist leicht. Die Schlitten sind leicht.</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">liegt — se află, este, stă culcat</div><div class=\"kurss-example\">der Bleistift (blaiștift) — creion</div><div class=\"kurss-example\">einige (ainighe) — câțiva, unii</div><div class=\"kurss-example\">hinlegen — a pune jos</div><div class=\"kurss-example\">legt hin — pune jos</div><div class=\"kurss-example\">wieder (vider) — din nou</div><div class=\"kurss-example\">aufmachen — a deschide</div><div class=\"kurss-example\">er macht auf — el deschide</div><div class=\"kurss-example\">anspitzen (anșpițen) — a ascuți</div><div class=\"kurss-example\">er spitzt an — el ascute</div><div class=\"kurss-example\">sich setzen — a se așeza</div><div class=\"kurss-example\">setzt sich — se așază</div><div class=\"kurss-example\">der Schlüssel (șlüsel) — cheie</div><div class=\"kurss-example\">das Fenster (fenster) — fereastră</div><div class=\"kurss-example\">die Tafel (di tafel) — tablă</div><div class=\"kurss-example\">der Garten — grădină</div><div class=\"kurss-example\">der Löffel — lingură</div><div class=\"kurss-example\">zählen (țelen) — a număra</div><div class=\"kurss-example\">die Nadel — ac</div><div class=\"kurss-example\">was ist das — ce este asta?</div><div class=\"kurss-example\">der Hammer — ciocan</div><div class=\"kurss-example\">die Hämmer — ciocane</div><div class=\"kurss-example\">der Deckel (der dechel) — capac</div><div class=\"kurss-example\">der Teller — farfurie</div><div class=\"kurss-example\">der Wagen — căruță</div><div class=\"kurss-example\">der Schlitten — sanie</div><div class=\"kurss-example\">das Ding — lucru</div><div class=\"kurss-example\">die Dinge — lucruri</div><div class=\"kurss-example\">wie sind die Dinge? — cum sunt lucrurile?</div><div class=\"kurss-example\">voll (fol) — plin</div><div class=\"kurss-example\">leer (ler) — gol</div><div class=\"kurss-example\">schwer (șver) — greu</div><div class=\"kurss-example\">leicht — ușor</div><div class=\"kurss-example\">der Eimer — găleată</div><div class=\"kurss-example\">wieviel (vifil) — cât, câți</div><div class=\"kurss-example\">wieviel Nadeln — câte ace</div><div class=\"kurss-example\">hier (hir) — aici</div><div class=\"kurss-example\">dort — acolo</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ä este umlautul vocalei a și se pronunță ca un e închis, scurt sau lung.</div><div class=\"kurss-example\">Exemple: das Mädchen (met-hen), die Bänke (di benche), der Vater (der fater), die Väter (di feter).</div><div class=\"kurss-example\">ü este umlautul vocalei u. Când îl pronunți, rotunjește bine buzele și încearcă să spui i cu buzele rotunjite.</div><div class=\"kurss-example\">Exemple: fünf, der Schlüssel (șlüsel).</div><div class=\"kurss-example\">ö se pronunță cu buzele rotunjite, încercând să spui e: der Löffel.</div><div class=\"kurss-example\">O vocală dublată indică o vocală lungă: leer (ler).</div><div class=\"kurss-example\">Diftongul eu se pronunță ca oi: neun (noin).</div></div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Gramatică și explicații</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La prezent, prefixul accentuat al verbului compus se desparte de verb și stă la sfârșitul propoziției.</div><div class=\"kurss-example\">Exemple: hinlegen — er legt hin; aufmachen — er macht auf; anspitzen — er spitzt an.</div><div class=\"kurss-example\">Numeralul unu, folosit cu un substantiv, are forme pentru toate cele trei genuri: la masculin ein, la feminin eine, la neutru ein.</div><div class=\"kurss-example\">Exemple: ein Schüler — un elev; eine Schülerin — o elevă; ein Kind — un copil.</div><div class=\"kurss-example\">Numeralele: eins, zwei, drei, vier (fir), fünf, sechs (zecs), sieben (ziben), acht, neun (noin), zehn (țen).</div><div class=\"kurss-example\">În germană, verbul copulativ are o formă de singular și una de plural: der Schüler ist klein; die Schüler sind klein.</div><div class=\"kurss-example\">Pronumele demonstrativ acesta se schimbă în română după număr și gen, dar în germană se folosește o singură formă: das.</div><div class=\"kurss-example\">Exemple: acesta este un ciocan — das ist ein Hammer; acesta este un ac — das ist eine Nadel; acestea sunt ciocane — das sind Hämmer; acestea sunt ace — das sind Nadeln.</div><div class=\"kurss-example\">Der Wagen — căruță și der Schlitten — sanie se folosesc în germană atât la singular, cât și la plural.</div><div class=\"kurss-example\">Substantivele masculine și neutre terminate în -er, -el, -en adesea nu primesc terminație la plural.</div><div class=\"kurss-example\">Exemple: der Hammer — die Hämmer; der Garten — die Gärten; das Fenster — die Fenster; das Messer — die Messer.</div><div class=\"kurss-example\">Substantivele feminine terminate în -el, -er primesc -n la plural.</div><div class=\"kurss-example\">Exemple: die Nadel — die Nadeln; die Feder — die Federn.</div><div class=\"kurss-example\">Excepții: die Mutter (mamă) — die Mütter (mame); die Tochter (fiică) — die Töchter (fiice).</div><div class=\"kurss-example\">Articolul nehotărât nu are plural: das ist ein Wagen — das sind Wagen; das ist eine Nadel — das sind Nadeln.</div><div class=\"kurss-example\">În propoziția enunțiativă, predicatul verbal stă pe locul al doilea: er legt den Schlüssel hin; dann legt er den Schlüssel hin.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson6-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 6: cartonaș de traducere\"><span class=\"lesson1-training-progress\">Lecția 6 · Tradu: 1 / 21</span><span class=\"lesson1-training-text\">Paul ia un creion și desenează.</span></button><p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p></div></div>\n    </details>\n  ",
  "kurssLesson5": "\n    <h3>Lecția 5</h3>\n    <p class=\"kurss-lesson-intro\">Wen?, acuzativul, sitzen, fragen și terminația -in.</p>\n\n    <details class=\"lesson1-accordion\" open>\n      <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">Wer sitzt und fragt? Der Lehrer sitzt und fragt.</div>\n        <div class=\"kurss-example\">Wer steht und antwortet? Der Schüler steht und antwortet.</div>\n        <div class=\"kurss-example\">Wie antwortet der Schüler? Der Schüler antwortet gut.</div>\n        <div class=\"kurss-example\">Wen lobt der Lehrer? Der Lehrer lobt den Schüler.</div>\n        <div class=\"kurss-example\">Wie ist der Schüler? Der Schüler ist klein.</div>\n        <div class=\"kurss-example\">Ist der Schüler klein oder groß? Er ist klein.</div>\n        <div class=\"kurss-example\">Wen fragt die Lehrerin? Die Lehrerin fragt die Schülerin.</div>\n        <div class=\"kurss-example\">Wie antwortet die Schülerin? Die Schülerin antwortet schlecht.</div>\n        <div class=\"kurss-example\">Was tut die Lehrerin? Sie tadelt die Schülerin.</div>\n        <div class=\"kurss-example\">Die Schülerin ist nicht klein, sie ist groß.</div>\n        <div class=\"kurss-example\">Ein Kind spielt. Das Kind ist artig.</div>\n        <div class=\"kurss-example\">Die Mutter liebt das Kind. Der Vater lobt das Kind.</div>\n      </div></div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">sitzen (zițen) — a ședea</div>\n        <div class=\"kurss-example\">fragen (fraghen) — a întreba</div>\n        <div class=\"kurss-example\">der Lehrer (der lerer) — profesorul</div>\n        <div class=\"kurss-example\">gut (gut) — bine</div>\n        <div class=\"kurss-example\">wen (ven) — pe cine</div>\n        <div class=\"kurss-example\">loben — a lăuda</div>\n        <div class=\"kurss-example\">der Schüler (șüler) — elevul</div>\n        <div class=\"kurss-example\">klein — mic</div>\n        <div class=\"kurss-example\">groß (gros) — mare</div>\n        <div class=\"kurss-example\">die Lehrerin — profesoara</div>\n        <div class=\"kurss-example\">die Schülerin — eleva</div>\n        <div class=\"kurss-example\">schlecht (șleht) — rău, prost</div>\n        <div class=\"kurss-example\">tadeln — a mustra, a dojeni</div>\n        <div class=\"kurss-example\">oder (oder) — sau</div>\n        <div class=\"kurss-example\">das Kind (chint) — copilul</div>\n        <div class=\"kurss-example\">artig (artih) — cuminte</div>\n        <div class=\"kurss-example\">die Mutter — mama</div>\n        <div class=\"kurss-example\">lieben (liben) — a iubi</div>\n        <div class=\"kurss-example\">der Vater (fater) — tatăl</div>\n      </div></div>\n    </details>\n\n        <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\">\n        <div class=\"kurss-example\">tz este un z dublat și se pronunță ca z german, adică ț: sitzen (zițen).</div>\n        <div class=\"kurss-example\">În cuvintele germane, v se pronunță ca f: der Vater (fater).</div>\n        <div class=\"kurss-example\">ß se numește eszett și se pronunță ca s românesc: groß (gros), weiß (vais).</div>\n      </div></div>\n    </details>\n\n<details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content lesson1-grammar-content\">\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Nominativul și acuzativul</h4><div class=\"lesson1-grammar-note\">În limba română, nominativul răspunde la întrebările cine? ce?, iar acuzativul la întrebările pe cine? ce?.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În germană, întrebarea la nominativ este wer? pentru persoane și was? pentru obiecte.</div><div class=\"kurss-example\">La acuzativ, întrebarea este wen? pentru persoane și was? pentru obiecte.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Schimbarea articolelor la acuzativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Akkusativ: den Vater, die Mutter, das Kind.</div><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">sitzen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich sitze</div><div class=\"kurss-example\">du sitzt</div><div class=\"kurss-example\">er/sie/es sitzt</div><div class=\"kurss-example\">wir sitzen</div><div class=\"kurss-example\">ihr sitzt</div><div class=\"kurss-example\">sie sitzen</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">fragen + acuzativ</h4><div class=\"lesson1-grammar-note\">În germană, verbul fragen cere acuzativul.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wen fragt der Lehrer?</div><div class=\"kurss-example\">Der Lehrer fragt den Schüler.</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Terminația -in</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Multe substantive feminine se formează cu terminația -in.</div><div class=\"kurss-example\">die Lehrerin</div><div class=\"kurss-example\">die Schülerin</div></div></section>\n        <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\">Locul verbului</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În propoziția enunțiativă, verbul stă pe locul al doilea.</div><div class=\"kurss-example\">Dann geht das Mädchen hinaus und arbeitet.</div><div class=\"kurss-example\">Das Mädchen geht dann hinaus und arbeitet.</div></div></section>\n      </div>\n    </details>\n\n    <details class=\"lesson1-accordion\">\n      <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n      <div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson5-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 5: cartonaș de traducere\"><span class=\"lesson1-training-progress\">Lecția 5 · Tradu: 1 / 16</span><span class=\"lesson1-training-text\">Pe cine iubește tatăl?</span></button><p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p></div></div>\n    </details>\n  ",
  "kurssLesson4": "            <h3>Lecția 4</h3>\n            <p class=\"kurss-lesson-intro\">Acuzativul, nehmen, hinlegen, hinausgehen și adjectivele.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Paul kommt und nimmt einen Federhalter.</div><div class=\"kurss-example\">Er zeigt den Federhalter.</div><div class=\"kurss-example\">Er fragt: „Wie ist der Federhalter?“</div><div class=\"kurss-example\">Olga antwortet: „Der Federhalter ist schwarz.“</div><div class=\"kurss-example\">Ist der Federhalter weiß? Nein, der Federhalter ist nicht weiß, er ist schwarz.</div><div class=\"kurss-example\">Marie kommt und nimmt eine Feder.</div><div class=\"kurss-example\">Sie fragt: „Wie ist die Feder?“</div><div class=\"kurss-example\">Olga antwortet: „Die Feder ist spitz.“</div><div class=\"kurss-example\">Ist die Feder stumpf? Nein, die Feder ist nicht stumpf, sie ist spitz.</div><div class=\"kurss-example\">Was legt das Mädchen hin? Es legt die Feder hin.</div><div class=\"kurss-example\">Was nimmst du? Ich nehme ein Messer.</div><div class=\"kurss-example\">Wie ist das Messer? Das Messer ist scharf.</div><div class=\"kurss-example\">Ist das Messer stumpf? Nein, es ist nicht stumpf, es ist scharf.</div><div class=\"kurss-example\">Was legst du hin? Ich lege das Messer, die Feder und den Federhalter hin.</div><div class=\"kurss-example\">Dann gehe ich hinaus und arbeite.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">nehmen (nemen) — a lua</div><div class=\"kurss-example\">er nimmt (nimt) — el ia</div><div class=\"kurss-example\">der Federhalter (der federhalter) — tocul</div><div class=\"kurss-example\">einen Federhalter — un toc</div><div class=\"kurss-example\">zeigen — a arăta</div><div class=\"kurss-example\">schwarz (șvarț) — negru</div><div class=\"kurss-example\">weiß (vais) — alb</div><div class=\"kurss-example\">die Feder (di feder) — penița</div><div class=\"kurss-example\">eine Feder — o peniță</div><div class=\"kurss-example\">spitz (șpiț) — ascuțit</div><div class=\"kurss-example\">hinlegen — a pune jos</div><div class=\"kurss-example\">legt hin — pune jos</div><div class=\"kurss-example\">das Mädchen (met-hen) — fata</div><div class=\"kurss-example\">das Messer — cuțitul</div><div class=\"kurss-example\">ein Messer — un cuțit</div><div class=\"kurss-example\">scharf — tăios</div><div class=\"kurss-example\">stumpf (ștumpf) — tocit, bont</div><div class=\"kurss-example\">dann — apoi</div><div class=\"kurss-example\">hinaus — afară</div><div class=\"kurss-example\">hinausgehen — a ieși, a ieși afară</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Terminațiile -en, -er, -el sunt neaccentuate, de aceea e din aceste terminații se aude slab: kommen, nehmen, der Federhalter.</div><div class=\"kurss-example\">În germană, h poate fi fie un sunet, fie un semn de lungire a vocalei precedente.</div><div class=\"kurss-example\">Dacă h este semn de lungire, nu se pronunță ca sunet: nehmen (nemen).</div><div class=\"kurss-example\">Dacă după vocală urmează o singură consoană, vocala se pronunță lung: die (di) Feder (feder), den (den).</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Acuzativul</h4><div class=\"lesson1-grammar-note\">La feminin și neutru, acuzativul este identic cu nominativul. Se schimbă doar masculinul.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Nominativ: der Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Akkusativ: den Federhalter, die Feder, das Messer.</div><div class=\"kurss-example\">Nominativ: ein Federhalter, eine Feder, ein Messer.</div><div class=\"kurss-example\">Akkusativ: einen Federhalter, eine Feder, ein Messer.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>nehmen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich nehme</div><div class=\"kurss-example\">du nimmst</div><div class=\"kurss-example\">er/sie nimmt</div><div class=\"kurss-example\">wir nehmen</div><div class=\"kurss-example\">ihr nehmt</div><div class=\"kurss-example\">sie nehmen</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Pronumele</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er — masculin</div><div class=\"kurss-example\">sie — feminin</div><div class=\"kurss-example\">es — neutru</div><div class=\"kurss-example\">la plural — sie</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Verbele separabile</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">hinlegen → ich lege das Messer hin</div><div class=\"kurss-example\">hinausgehen → Marie geht hinaus</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>Adjectivele</h4><div class=\"lesson1-grammar-note\">Dacă adjectivul este nume predicativ în propoziție, nu se schimbă nici după gen, nici după număr.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist klein</div><div class=\"kurss-example\">die Feder ist klein</div><div class=\"kurss-example\">das Messer ist klein</div><div class=\"kurss-example\">die Messer sind klein</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>6</span>Negația cu nicht</h4><div class=\"lesson1-grammar-note\">Dacă nicht neagă un adjectiv, el stă înaintea cuvântului negat.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">der Federhalter ist nicht weiß</div><div class=\"kurss-example\">das Messer ist nicht scharf</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>7</span>-chen / -lein</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Substantivele cu terminația -chen și -lein sunt neutre: das Mädchen.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson4-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 4: cartonaș de traducere\"><span class=\"lesson1-training-progress\">Lecția 4 · Tradu: 1 / 16</span><span class=\"lesson1-training-text\">Fata ia un toc.</span></button><p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p></div></div></details>",
  "kurssLesson3": "            <h3>Lecția 3</h3>\n            <p class=\"kurss-lesson-intro\">A treia lecție: dialoguri, cuvinte, pronunție, gramatică și traducere.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Wer rechnet und zeichnet?<br>Wir rechnen und zeichnen.</div><div class=\"kurss-example\">Wer kommt?<br>Paul und Anna kommen.</div><div class=\"kurss-example\">Was steht hier?<br>Hier steht ein Tisch.</div><div class=\"kurss-example\">Was steht dort?<br>Dort steht eine Bank.</div><div class=\"kurss-example\">Was liegt hier?<br>Hier liegt ein Buch.</div><div class=\"kurss-example\">Was liegt dort?<br>Dort liegt ein Heft.</div><div class=\"kurss-example\">Was hängt hier?<br>Hier hängt ein Bild.</div><div class=\"kurss-example\">Was hängt dort?<br>Dort hängt eine Tafel.</div><div class=\"kurss-example\">Wie ist das Buch?<br>Das Buch ist dick.</div><div class=\"kurss-example\">Wie ist das Heft?<br>Das Heft ist dünn.</div><div class=\"kurss-example\">Wie ist die Bank?<br>Die Bank ist niedrig.</div><div class=\"kurss-example\">Wie ist der Tisch?<br>Der Tisch ist hoch.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wer — cine</div><div class=\"kurss-example\">was — ce</div><div class=\"kurss-example\">hier — aici</div><div class=\"kurss-example\">dort — acolo</div><div class=\"kurss-example\">der Tisch — masa</div><div class=\"kurss-example\">ein Tisch — o masă</div><div class=\"kurss-example\">die Bank — banca</div><div class=\"kurss-example\">eine Bank — o bancă</div><div class=\"kurss-example\">liegen — a sta culcat, a se afla în poziție orizontală</div><div class=\"kurss-example\">liegt hier ein Buch? — aici este / se află o carte?</div><div class=\"kurss-example\">das Buch — cartea</div><div class=\"kurss-example\">ein Buch — o carte</div><div class=\"kurss-example\">hängen — a atârna</div><div class=\"kurss-example\">das Bild — tabloul</div><div class=\"kurss-example\">ein Bild — un tablou</div><div class=\"kurss-example\">die Tafel — tabla</div><div class=\"kurss-example\">eine Tafel — o tablă</div><div class=\"kurss-example\">wie — cum, ce fel de</div><div class=\"kurss-example\">ist — este</div><div class=\"kurss-example\">dick — gros</div><div class=\"kurss-example\">das Heft — caietul</div><div class=\"kurss-example\">ein Heft — un caiet</div><div class=\"kurss-example\">dünn — subțire</div><div class=\"kurss-example\">niedrig — jos, scund</div><div class=\"kurss-example\">hoch — înalt</div></div></div></details>\n                        <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În germană, sunetul i lung se scrie ie: liegen (lighen), hier (hir), wie (vi).</div><div class=\"kurss-example\">ck este un k dublu: dick (dikk).</div><div class=\"kurss-example\">La adjective și adverbe, terminația -ig sună ca un -ich ușor: niedrig (nidrih).</div><div class=\"kurss-example\">Dacă după -ig urmează e, adică -ige, g se pronunță ca un g clar: niedrige (nidrighe) Bänke.</div></div></div></details>\n<details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Subiectul</h4><div class=\"lesson1-grammar-note\">În germană, subiectul răspunde la întrebarea wer? / was? și stă în nominativ.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Cu wer? se întreabă despre persoane.</div><div class=\"kurss-example\">Cu was? se întreabă despre obiecte.</div><div class=\"kurss-example\">Wer singt? — Sie singt.</div><div class=\"kurss-example\">Was liegt hier? — Hier liegt ein Buch.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Articolele</h4><div class=\"lesson1-grammar-note\">În germană substantivul are 3 genuri: masculin, feminin și neutru. Înaintea substantivului stă de obicei un cuvânt mic numit articol. Acest cuvânt nu se traduce separat.</div><h5 class=\"lesson2-subtitle\">Articolul hotărât</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculin — der</div><div class=\"kurss-example\">feminin — die</div><div class=\"kurss-example\">neutru — das</div><div class=\"kurss-example\">La plural, articolul hotărât este die pentru toate cele trei genuri.</div><div class=\"kurss-example\">der Tisch — die Tische</div><div class=\"kurss-example\">die Bank — die Bänke</div><div class=\"kurss-example\">das Heft — die Hefte</div></div><h5 class=\"lesson2-subtitle\">Articolul nehotărât</h5><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">masculin — ein</div><div class=\"kurss-example\">feminin — eine</div><div class=\"kurss-example\">neutru — ein</div><div class=\"kurss-example\">Articolul nehotărât nu are plural.</div><div class=\"kurss-example\">ein Tisch — Tische</div><div class=\"kurss-example\">ein Heft — Hefte</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Numele proprii</h4><div class=\"lesson1-grammar-note\">Înaintea numelor proprii nu se folosește articolul.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans spielt, aber Marie singt.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>Locul verbului</h4><div class=\"lesson1-grammar-note\">În propoziția enunțiativă, verbul stă pe locul al doilea.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hier hängt eine Karte.</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>5</span>stehen / liegen / hängen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În germană, despre obiectele așezate vertical se spune că obiectul stă în picioare:<br>der Tisch steht<br>die Bank steht</div><div class=\"kurss-example\">Despre obiectele aflate în poziție orizontală se spune că stau culcate:<br>das Buch liegt<br>das Heft liegt</div><div class=\"kurss-example\">Obiectele pot și să atârne:<br>die Karte hängt<br>die Tafel hängt</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson3-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 3: cartonaș de traducere\"><span class=\"lesson1-training-progress\">Lecția 3 · Tradu: 1 / 22</span><span class=\"lesson1-training-text\">Tu socotești?</span></button><p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p></div></div></details>",
  "kurssLesson7": "            <h3>Lecția 7</h3>\n            <p class=\"kurss-lesson-intro\">A șaptea lecție: modul imperativ, forma de politețe și pluralul.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Dialoguri / propoziții</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Hans, singe ein Lied! Was tust du? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans und Olga, singt ein Lied! Was tut ihr? Wir singen ein Lied.</div><div class=\"kurss-example\">Fräulein Müller, singen Sie, bitte, ein Lied! Was tun Sie? Ich singe ein Lied.</div><div class=\"kurss-example\">Hans, zähle die Teller! Was tut Hans? Er zählt die Teller.</div><div class=\"kurss-example\">Hans und Olga, zählt die Teller! Was tun Hans und Olga? Sie zählen die Teller.</div><div class=\"kurss-example\">Fräulein Müller, zählen Sie, bitte, die Teller!</div><div class=\"kurss-example\">Hans, öffne das Fenster! Was tut Hans? Er öffnet das Fenster.</div><div class=\"kurss-example\">Hans und Olga, öffnet die Fenster! Was tun Hans und Olga? Sie öffnen die Fenster.</div><div class=\"kurss-example\">Fräulein Müller, öffnen Sie, bitte, alle Fenster!</div><div class=\"kurss-example\">Fräulein Müller öffnet alle Fenster.</div><div class=\"kurss-example\">Das ist der Spiegel. Das sind die Spiegel.</div><div class=\"kurss-example\">Das ist der Lappen. Das sind die Lappen.</div><div class=\"kurss-example\">Das ist der Spaten. Das sind die Spaten.</div><div class=\"kurss-example\">Das ist der Besen. Das sind die Besen.</div><div class=\"kurss-example\">Das ist die Schaufel. Das sind die Schaufeln.</div><div class=\"kurss-example\">Das ist die Schüssel. Das sind die Schüsseln.</div><div class=\"kurss-example\">Das ist das Zimmer. Das sind die Zimmer.</div><div class=\"kurss-example\">Das ist das Ufer. Das sind die Ufer.</div></div></div>\n            </details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">singen — a cânta</div><div class=\"kurss-example\">singe — cântă</div><div class=\"kurss-example\">singt — cântați</div><div class=\"kurss-example\">singen Sie — cântați</div><div class=\"kurss-example\">das Lied (das lit) — cântec</div><div class=\"kurss-example\">Sie — dumneavoastră</div><div class=\"kurss-example\">zählen — a număra</div><div class=\"kurss-example\">das Fräulein (froilain) — domnișoară</div><div class=\"kurss-example\">der Müller — morar</div><div class=\"kurss-example\">öffnen — a deschide</div><div class=\"kurss-example\">das Fenster (fenster) — fereastră</div><div class=\"kurss-example\">alle — toți</div><div class=\"kurss-example\">der Spiegel (șpighel) — oglindă</div><div class=\"kurss-example\">der Lappen — cârpă</div><div class=\"kurss-example\">der Spaten — cazma, hârleț</div><div class=\"kurss-example\">der Besen — mătură</div><div class=\"kurss-example\">die Schaufel — lopățică, făraș</div><div class=\"kurss-example\">die Schüssel — castron</div><div class=\"kurss-example\">das Zimmer — cameră</div><div class=\"kurss-example\">das Ufer (ufer) — mal</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La începutul cuvântului sau al silabei, sp se pronunță ca șp: der Spiegel (der șpighel).</div><div class=\"kurss-example\">sch se pronunță ca ș românesc: die Schaufel (di șaufel), die Schüssel (di șüsel).</div><div class=\"kurss-example\">Diftongul äu se pronunță ca oi românesc: das Fräulein (das froilain).</div></div></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content lesson1-grammar-content\"><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>1</span>Modul imperativ</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Imperativul la persoana a 2-a singular corespunde formei de persoana a 2-a singular a verbului fără terminația personală -st, la care se adaugă terminația -e.</div><div class=\"kurss-example\">Exemple: antworte!, arbeite!, öffne!, zeichne!</div><div class=\"kurss-example\">Foarte des terminația -e nu se folosește, iar forma de imperativ devine astfel monosilabică: geh!, steh!, komm!, tu!, sing!, frag!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>2</span>Imperativul la plural</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Forma de imperativ la persoana a 2-a plural este identică cu persoana a 2-a plural a prezentului, dar se folosește fără pronume.</div><div class=\"kurss-example\">Exemple: antwortet!, arbeitet!, öffnet!, zeichnet!, geht!, steht!, tut!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>3</span>Forma de politețe cu Sie</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Forma de politețe, corespunzătoare lui „dumneavoastră”, este identică cu persoana a 3-a plural. Pronumele Sie se scrie cu majusculă și stă după verb.</div><div class=\"kurss-example\">Exemple: antworten Sie!, arbeiten Sie!, öffnen Sie!, zeichnen Sie!, gehen Sie!, stehen Sie!, tun Sie!</div></div></section><section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>4</span>öffnen</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">La verbul öffnen, pentru o pronunție mai ușoară, la persoanele a 2-a și a 3-a singular și la persoana a 2-a plural se intercalează un e între temă și terminație: du öffnest, er öffnet, ihr öffnet.</div></div></section></div></details>\n            <details class=\"lesson1-accordion\"><summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Übung / Exercițiu</span><span class=\"lesson1-chevron\">⌄</span></summary><div class=\"lesson1-content\"><div class=\"lesson1-training-wrap\"><button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson7-exercise-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 7: cartonaș de exercițiu\"><span class=\"lesson1-training-progress\">Lecția 7 · Übung: 1 / 16</span><span class=\"lesson1-training-text\">fragen — a întreba</span></button><p class=\"lesson1-training-hint\">Atinge cartonașul ca să vezi formele de imperativ.</p></div></div></details>",
  "kurssLesson1": "            <h3>Lecția 1</h3>\n            <p class=\"kurss-lesson-intro\">Prima lecție: verbe la prezent, cuvinte, pronunție, gramatică și traducere.</p>\n            <details class=\"lesson1-accordion\" open>\n              <summary><span class=\"lesson1-number lesson1-number-red\">1.</span><span>Verbe la prezent</span><span class=\"lesson1-chevron\">⌃</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info\">Verbele și conjugarea lor la prezent.</div>\n                <div class=\"lesson1-verb-cards\">\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>kommen — a veni</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>komme</strong><span>eu vin</span><span>du</span><strong>kommst</strong><span>tu vii</span><span>er / sie</span><strong>kommt</strong><span>el / ea vine</span><span>wir</span><strong>kommen</strong><span>noi venim</span><span>ihr</span><strong>kommt</strong><span>voi veniți</span><span>sie / Sie</span><strong>kommen</strong><span>ei / ele vin; dumneavoastră veniți</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>gehen — a merge</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>gehe</strong><span>eu merg</span><span>du</span><strong>gehst</strong><span>tu mergi</span><span>er / sie</span><strong>geht</strong><span>el / ea merge</span><span>wir</span><strong>gehen</strong><span>noi mergem</span><span>ihr</span><strong>geht</strong><span>voi mergeți</span><span>sie / Sie</span><strong>gehen</strong><span>ei / ele merg; dumneavoastră mergeți</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>stehen — a sta în picioare</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>stehe</strong><span>eu stau</span><span>du</span><strong>stehst</strong><span>tu stai</span><span>er / sie</span><strong>steht</strong><span>el / ea stă</span><span>wir</span><strong>stehen</strong><span>noi stăm</span><span>ihr</span><strong>steht</strong><span>voi stați</span><span>sie / Sie</span><strong>stehen</strong><span>ei / ele stau; dumneavoastră stați</span></div>\n                  </article>\n                  <article class=\"lesson1-verb-card\">\n                    <h4><span class=\"lesson1-verb-icon\">♟</span>singen — a cânta</h4>\n                    <div class=\"lesson1-conjugation\"><span>ich</span><strong>singe</strong><span>eu cânt</span><span>du</span><strong>singst</strong><span>tu cânți</span><span>er / sie</span><strong>singt</strong><span>el / ea cântă</span><span>wir</span><strong>singen</strong><span>noi cântăm</span><span>ihr</span><strong>singt</strong><span>voi cântați</span><span>sie / Sie</span><strong>singen</strong><span>ei / ele cântă; dumneavoastră cântați</span></div>\n                  </article>\n                </div>\n                <section class=\"lesson1-block\">\n                  <h4>Exemple</h4>\n                  <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Stehst du?<br>Ja, ich stehe.</div><div class=\"kurss-example\">Steht Albert?<br>Ja, er steht.</div><div class=\"kurss-example\">Steht Marta?<br>Ja, sie steht.</div><div class=\"kurss-example\">Wer kommt und singt?<br>Albert und Marta kommen und singen.</div><div class=\"kurss-example\">Geht ihr?<br>Ja, wir gehen.</div><div class=\"kurss-example\">Wer steht und singt?<br>Albert und Marta stehen und singen.</div></div>\n                </section>\n              </div>\n            </details>\n            <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-green\">2.</span><span>Cuvinte</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-info lesson1-vardini-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>Pronunția aproximativă a cuvintelor este dată în paranteze cu litere românești.<br>Acest lucru este valabil și în lecțiile următoare.</span></div>\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">wir (vir) — noi</div><div class=\"kurss-example\">În cuvântul „wir”, litera i se pronunță lung.</div><div class=\"kurss-example\">kommen (comen) — a veni</div><div class=\"kurss-example\">gehen (ghe-en) — a merge</div><div class=\"kurss-example\">stehen (ște-en) — a sta în picioare</div><div class=\"kurss-example\">singen (zinghen) — a cânta</div><div class=\"kurss-example\">du (du) kommst — tu vii</div><div class=\"kurss-example\">er (er) kommt — el vine</div><div class=\"kurss-example\">sie (zi) kommt — ea vine</div><div class=\"kurss-example\">wer (ver) — cine?</div><div class=\"kurss-example\">ja (ia) — da</div></div>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-purple\">3.</span><span>Pronunție</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-card-grid\"><div class=\"kurss-example\">Pronunția corectă a cuvintelor, notată cu litere românești, este dată în lecții.</div><div class=\"kurss-example\">Wir (vir) — noi. În cuvântul wir, i se pronunță întotdeauna lung.</div></div>\n              </div>\n            </details>\n<details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-blue\">4.</span><span>Gramatică</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content lesson1-grammar-content\">\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>∞</span>Infinitivul</h4><div class=\"lesson1-grammar-note\">Forma de bază a verbului. De obicei, infinitivul se termină în -en.</div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">kommen</div><div class=\"kurss-example\">gehen</div><div class=\"kurss-example\">stehen</div><div class=\"kurss-example\">singen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♟</span>Terminațiile prezentului</h4><div class=\"lesson1-ending-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><div class=\"lesson1-ending-info-body\"><p><strong>Elimină <span class=\"lesson1-ending-accent\">-en</span> din forma de bază a verbului și adaugă terminația.</strong></p><p>Exemplu: kommen → komm + terminație</p><div class=\"lesson1-ending-process\" aria-label=\"Cum se formează prezentul\"><div class=\"lesson1-ending-step\"><strong>kommen</strong><span>forma de bază</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>elimină <span class=\"lesson1-ending-accent\">-en</span></strong><span>rămâne rădăcina</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>komm</strong><span>rădăcina</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-step\"><strong>adaugă terminația</strong><span>e / st / t</span></div><span class=\"lesson1-ending-arrow\">→</span><div class=\"lesson1-ending-results\"><div>komm + <span class=\"lesson1-ending-accent\">e</span> = <strong>komme</strong></div><div>komm + <span class=\"lesson1-ending-accent\">st</span> = <strong>kommst</strong></div><div>komm + <span class=\"lesson1-ending-accent\">t</span> = <strong>kommt</strong></div></div></div></div></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich → -e</div><div class=\"kurss-example\">du → -st</div><div class=\"kurss-example\">er / sie → -t</div><div class=\"kurss-example\">wir → -en</div><div class=\"kurss-example\">ihr → -t</div><div class=\"kurss-example\">sie → -en</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>●</span>Exemple</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">ich komme</div><div class=\"kurss-example\">du kommst</div><div class=\"kurss-example\">er kommt</div><div class=\"kurss-example\">wir kommen</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>?</span>Propoziții interogative</h4><div class=\"lesson1-grammar-info\"><span class=\"lesson1-info-icon\" aria-hidden=\"true\">i</span><span>În propoziția interogativă germană, verbul trece de obicei pe primul loc.</span></div><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">În limba română:<br>Tu vii.<br>Vii tu?</div><div class=\"kurss-example\">În limba germană:<br>Du kommst.<br>Kommst du?</div><div class=\"kurss-example\">du kommst — tu vii<br>kommst du? — vii tu?</div><div class=\"kurss-example\">er singt — el cântă<br>singt er? — cântă el?</div></div></section>\n                <section class=\"lesson1-block\"><h4 class=\"lesson1-grammar-header\"><span>♣</span>Diferența de persoană</h4><div class=\"lesson1-card-grid\"><div class=\"kurss-example\">er kommt — el vine</div><div class=\"kurss-example\">sie kommt — ea vine</div><div class=\"kurss-example\">sie kommen — ei / ele vin</div></div></section>\n              </div>\n            </details>\n                        <details class=\"lesson1-accordion\">\n              <summary><span class=\"lesson1-number lesson1-number-orange\">5.</span><span>Tradu</span><span class=\"lesson1-chevron\">⌄</span></summary>\n              <div class=\"lesson1-content\">\n                <div class=\"lesson1-training-wrap\">\n                  <button class=\"lesson1-training-flashcard\" type=\"button\" data-lesson1-training-card data-training-index=\"0\" data-showing-back=\"false\" aria-label=\"Lecția 1: cartonaș de exersare\">\n                    <span class=\"lesson1-training-progress\">Lecția 1 · Tradu: 1 / 11</span>\n                    <span class=\"lesson1-training-text\">Vii?</span>\n                  </button>\n                  <p class=\"lesson1-training-hint\">Fă clic pe cartonaș ca să vezi traducerea în germană. După răspuns, următorul clic arată cartonașul următor.</p>\n                </div>\n              </div>\n            </details>"
};

